  const magnitude = nanoseconds < 0 ? -nanoseconds : nanoseconds;
  const fractional = (magnitude % 1_000_000n).toString().padStart(6, "0").replace(/0+$/u, "");
  return `${nanoseconds < 0 ? "-" : ""}${magnitude / 1_000_000n}${fractional ? `.${fractional}` : ""}`;
